16	export const isImageAttachment = (attachment: Attachment): boolean => getAttachmentType(attachment) === "image/*";
17	export const isVideoAttachment = (attachment: Attachment): boolean => getAttachmentType(attachment) === "video/*";
18	export const isAudioAttachment = (attachment: Attachment): boolean => getAttachmentType(attachment) === "audio/*";
