20	export const separateAttachments = (attachments: Attachment[]): AttachmentGroups => {
21	  return attachments.reduce<AttachmentGroups>(
22	    (groups, attachment) => {
23	      if (isImageAttachment(attachment) || isVideoAttachment(attachment)) {
24	        groups.visual.push(attachment);
25	      } else if (isAudioAttachment(attachment)) {
26	        groups.audio.push(attachment);
27	      } else {
28	        groups.docs.push(attachment);
29	      }
30	
31	      return groups;
32	    },
33	    {
34	      visual: [],
35	      audio: [],
36	      docs: [],
37	    },
38	  );
39	};
